    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9
        };

        var orderSizeBonus = subtotalCents switch
        {
            < 50_00 => 0,
            < 200_00 => 1,
            _ => 3
        };

        var effectiveRate = Math.Min(baseRate + orderSizeBonus, 10);
        var discountCents = subtotalCents * effectiveRate / 100;

        return subtotalCents - discountCents;
    }
}
